void kernel_main() {
    // runtime args: [num_tiles]
    uint32_t num_tiles = get_arg_val<uint32_t>(0);

    // initialize needed ops for f32 accuracy
    mul_binary_tile_init();
    sub_binary_tile_init();
    exp_tile_init();

    for (uint32_t i = 0; i < num_tiles; ++i) {
        // wait for one input tile in CB 0
        cb_wait_front(cb_in, tile_size_bytes);
        uint32_t l1_addr = get_read_ptr(cb_in);
        // copy input tile into tile register 0
        copy_tile(l1_addr, 0);
        // release input tile from CB
        cb_pop_front(cb_in, tile_size_bytes);

        // t = a * a -> reg1
        mul_binary_tile(0, 0, 1);
        // t2 = t * t -> reg2 (this is (a*a)*(a*a) = a^4)
