        sub_binary_tile(0, 0, 3);
        // one tile = exp(0) = 1.0 -> overwrite reg3
        exp_tile(3);
        // out = t2 - 1 -> reg4
        sub_binary_tile(2, 3, 4);

        // write result tile to CB 16
        cb_reserve_back(cb_out, tile_size_bytes);
        uint32_t out_l1 = get_write_ptr(cb_out);
        copy_tile(4, out_l1);
        cb_push_back(cb_out, tile_size_bytes);
    }
}
