// Computes out = (a*a + 1)*(a*a - 1) = a^4 - 1

#include "compute_kernel_api/common.h"
#include "compute_kernel_api/tile_move_copy.h"
#include "compute_kernel_api/eltwise_binary.h"
#include "compute_kernel_api/eltwise_unary.h"
#include "compute_kernel_api/eltwise_unary/exp.h"

constexpr uint32_t cb_in = 0;
constexpr uint32_t cb_out = 16;
constexpr uint32_t tile_size_bytes = 32 * 32 * 4; // float32 tile size

void kernel_main() {
    // runtime args: [num_tiles]
    uint32_t num_tiles = get_arg_val<uint32_t>(0);

    // initialize SFPU binary ops and exp for f32 accuracy
    mul_binary_tile_init();
    sub_binary_tile_init();
    exp_tile_init();

    for (uint32_t t = 0; t < num_tiles; ++t) {
        // -------- read input tile --------
        // wait until a tile is available in CB 0
        cb_wait_front(cb_in, tile_size_bytes);
        uint32_t l1_addr = get_read_ptr(cb_in);
        // copy tile from L1 to tile register 0
        copy_tile(l1_addr, 0);
        // release tile from CB
        cb_pop_front(cb_in, tile_size_bytes);

        // -------- compute a*a (t) --------
        mul_binary_tile(0, 0, 1); // reg1 = a * a

        // -------- compute a^4 (t2) --------
        mul_binary_tile(1, 1, 2); // reg2 = t * t = a^4

        // -------- generate constant 1.0 tile --------
        // zero tile by subtracting a from itself
        sub_binary_tile(0, 0, 3); // reg3 = 0
        // exp(0) = 1.0 (SFPU exp is f32 accurate with HiFi4)
        exp_tile(3); // reg3 now holds 1.0

        // -------- compute out = a^4 - 1 --------
        sub_binary_tile(2, 3, 4); // reg4 = a^4 - 1

        // -------- write output tile --------
        cb_reserve_back(cb_out, tile_size_bytes);
        uint32_t out_l1 = get_write_ptr(cb_out);
        copy_tile(4, out_l1);
        cb_push_back(cb_out, tile_size_bytes);
    }
}
"}

